# owner: platform
"""Seating charts: students sorted by last name, split into rows."""

import rosterkit.models


def seating_rows(*, students, seats_per_row):
    """Return one text line per row, e.g. 'Row 1: Dunmere, Piet | ...'.

    Raises ValueError if seats_per_row is below one or there are no
    students.
    """
    if seats_per_row < 1:
        raise ValueError('seats_per_row must be at least 1')
    if not students:
        raise ValueError('no students to seat')
    ordered = sorted(
        students,
        key=lambda s: (s.last_name.lower(), s.first_name.lower()),
    )
    lines = []
    for start in range(0, len(ordered), seats_per_row):
        names = []
        for student in ordered[start:start + seats_per_row]:
            names.append(student.display_name)
        number = start // seats_per_row + 1
        lines.append('Row ' + str(number) + ': ' + ' | '.join(names))
    return lines
EOF
cat > tests/test_seating.py <<'EOF'
# owner: platform
import unittest

import rosterkit.models
import rosterkit.seating


def make(last, first):
    return rosterkit.models.Student('id', last, first, 'A')


class SeatingTests(unittest.TestCase):
    def test_sorted_by_last_name_and_split_into_rows(self):
        students = [
            make('Halloway', 'Juno'),
            make('Dunmere', 'Piet'),
            make('Abbott', 'Sam'),
        ]
        rows = rosterkit.seating.seating_rows(
            students=students, seats_per_row=2
        )
        self.assertEqual(
            rows,
            [
                'Row 1: Abbott, Sam | Dunmere, Piet',
                'Row 2: Halloway, Juno',
            ],
        )

    def test_same_last_name_falls_back_to_first_name(self):
        students = [make('Lee', 'Zed'), make('Lee', 'Amy')]
        rows = rosterkit.seating.seating_rows(
            students=students, seats_per_row=5
        )
        self.assertEqual(rows, ['Row 1: Lee, Amy | Lee, Zed'])

    def test_zero_or_negative_seats_raise(self):
        students = [make('Lee', 'Amy')]
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                rosterkit.seating.seating_rows(
                    students=students, seats_per_row=seats
                )

    def test_no_students_raise(self):
        with self.assertRaises(ValueError):
            rosterkit.seating.seating_rows(
                students=[], seats_per_row=3
            )

    def test_arguments_are_keyword_only(self):
        with self.assertRaises(TypeError):
            rosterkit.seating.seating_rows([make('A', 'B')], 2)


if __name__ == '__main__':
    unittest.main()
